<?php declare(strict_types=1);
use Kulturhus\Native\Shared\Db;
use Kulturhus\Native\Cms\{Media,WebsiteDocuments,FieldPolicy,ContentLists,PublicSearch,Articles};
require_once __DIR__.'/own-website-pdf.php';
$assetRoot=dirname(getenv('KH_NATIVE_TEST_CONFIG')).'/field-policy-assets';mkdir($assetRoot,0700);$media=new Media($db,$admin,$assetRoot.'/media');$picture=[];$exactAssets=[];
for($i=0;$i<2;$i++){$png=$assetRoot.'/'.$i.'.png';$im=imagecreatetruecolor(12,8);imagefill($im,0,0,imagecolorallocate($im,40,70*$i,90));imagepng($im,$png);imagedestroy($im);$picture[]=$media->upload($png,'Own field image '.$i.'.png','Own original field credit '.$i);foreach(['original','large','medium','thumb']as$size){$variant=$media->variant($picture[$i]['id'],$size);$exactAssets[$variant['path']]=hash_file('sha256',$variant['path']);}}
$pdf=ownWebsitePdf('Own field policy private PDF original');$pdfPath=$assetRoot.'/own.pdf';file_put_contents($pdfPath,$pdf);$documents=new WebsiteDocuments($db,$admin,$assetRoot.'/documents');$document=$documents->uploadMany([['path'=>$pdfPath,'name'=>'Own field policy original.pdf']])[0];
$imageField=$model->saveField(['key'=>'role_image','label'=>'Own referenced image','type'=>'media-reference']);$fileField=$model->saveField(['key'=>'role_file','label'=>'Own referenced PDF','type'=>'file-reference']);$prose=$model->saveField(['key'=>'role_prose','label'=>'Own searchable prose','type'=>'richtext']);$nestedPicture=$model->saveField(['key'=>'role_nested_image','label'=>'Own nested image','type'=>'media-reference']);$assetRows=$model->saveField(['key'=>'role_asset_rows','label'=>'Own original asset rows','type'=>'repeater','fields'=>['role_nested_image']]);
$model->saveTemplate(['key'=>'role_assets','label'=>'Own actual assets policy','fields'=>['role_image','role_file','role_prose','role_asset_rows']]);
$assetPage=$pages->save(['title'=>'Own actual public references','slug'=>'role-policy-assets','template'=>'role_assets','custom_fields'=>['role_image'=>$picture[0]['id'],'role_file'=>$document['id'],'role_prose'=>'<p>UniqueFieldPolicyPublicNeedle</p>','role_asset_rows'=>[['values'=>['role_nested_image'=>$picture[1]['id']]]]]]);$assetPage=$pages->publish($assetPage['id'],$assetPage['version']);
check($media->publicVariant($picture[0]['id'],'medium',$assetPage)!==null&&$media->publicVariant($picture[1]['id'],'medium')!==null&&$documents->publicFile($document['id'])!==null,'actual current default field bindings release scalar/nested image and PDF originals');
$search=new PublicSearch($db,$reader);check($search->page('UniqueFieldPolicyPublicNeedle')['total']===1,'actual public search initially matches the released richtext field');
$originalAssetPage=Db::run($db,'SELECT * FROM khcms_pages WHERE id=?',[$assetPage['id']])->fetch();$originalAssetRevisions=Db::run($db,'SELECT * FROM khcms_revisions WHERE page_id=? ORDER BY revision',[$assetPage['id']])->fetchAll();
foreach(['imageField','fileField','prose','nestedPicture']as$name)$$name=$model->saveField(array_replace($$name,['access'=>['read'=>'manage','edit'=>'manage']]),$$name['version']);
check($media->publicVariant($picture[0]['id'],'medium')===null&&$media->publicVariant($picture[0]['id'],'medium',$assetPage)===null&&$media->publicVariant($picture[1]['id'],'medium')===null&&$documents->publicFile($document['id'])===null,'actual current field revocation immediately withdraws scalar/nested image and PDF bytes');
check($search->page('UniqueFieldPolicyPublicNeedle')['total']===0&&$search->page('UniqueFieldPolicyPublicNeedle')['rows']===[],'actual public search removes protected matching text before count and snippets');
$publicPage=$pages->publicPage($assetPage['slug']);$publicList=$pages->publicList();$publicStream=iterator_to_array($pages->publicOriginals());
foreach([$publicPage,$publicList,$publicStream]as$view)check(!str_contains(json_encode($view,JSON_THROW_ON_ERROR),'UniqueFieldPolicyPublicNeedle')&&!str_contains(json_encode($view,JSON_THROW_ON_ERROR),$document['name']??'Own field policy original.pdf'),'actual public page/list/original stream redacts current forbidden text and file metadata');
check(Db::run($db,'SELECT * FROM khcms_pages WHERE id=?',[$assetPage['id']])->fetch()===$originalAssetPage&&Db::run($db,'SELECT * FROM khcms_revisions WHERE page_id=? ORDER BY revision',[$assetPage['id']])->fetchAll()===$originalAssetRevisions,'live field revocations preserve exact original source and historical publication bytes');
$independent=$pages->save(['title'=>'Own legitimate independent asset use','slug'=>'role-asset-independent','media_ids'=>[$picture[0]['id']],'document_links'=>[['id'=>$document['id'],'label'=>'Own legitimate document']]]);$independent=$pages->publish($independent['id'],$independent['version']);
check($media->publicVariant($picture[0]['id'],'medium')!==null&&$documents->publicFile($document['id'])!==null&&$media->publicVariant($picture[0]['id'],'medium',$assetPage)===null,'independent actual public bindings permit shared originals without authorizing forbidden source-specific metadata');
$independent=$pages->unpublish($independent['id'],$independent['version']);check($media->publicVariant($picture[0]['id'],'medium')===null&&$documents->publicFile($document['id'])===null,'withdrawing the only independent binding immediately closes the protected shared originals again');
// A new private original captures the strict definition; later model relaxation may expose only older open originals.
$privateAssets=$pages->save(['title'=>'Own historically protected assets','slug'=>'role-historic-assets','template'=>'role_assets','custom_fields'=>['role_image'=>$picture[0]['id'],'role_file'=>$document['id'],'role_prose'=>'<p>UniqueHistoricallyPrivateNeedle</p>','role_asset_rows'=>[]]]);$privateAssets=$pages->publish($privateAssets['id'],$privateAssets['version']);
foreach(['imageField','fileField','prose','nestedPicture']as$name)$$name=$model->saveField(array_replace($$name,['access'=>[]]),$$name['version']);
check($media->publicVariant($picture[0]['id'],'medium')!==null&&$media->publicVariant($picture[0]['id'],'medium',$privateAssets)===null&&$search->page('UniqueFieldPolicyPublicNeedle')['total']===1&&$search->page('UniqueHistoricallyPrivateNeedle')['total']===0,'current relaxation restores only originally public fields and keeps historical private bindings closed');
$assetPage=$pages->unpublish($assetPage['id'],$assetPage['version']);check($media->publicVariant($picture[0]['id'],'medium')===null&&$media->publicVariant($picture[1]['id'],'medium')===null&&$documents->publicFile($document['id'])===null,'historically private field references alone never authorize otherwise unused original bytes');
foreach($exactAssets as$path=>$hash)check(hash_file('sha256',$path)===$hash,'field permission checks preserve exact original image bytes');check(file_get_contents($documents->file($document['id'])['path'])===$pdf,'field permission checks preserve exact original PDF bytes');
// Actual public article and trusted event adapters apply the same anonymous projection.
foreach(['news','event']as$kind){$base=$model->template($kind);$model->saveTemplate(array_replace($base,['fields'=>['role_secret']]),$base['version']);$data=['title'=>'Own public '.$kind.' original','slug'=>'role-public-'.$kind,'template'=>$kind,'custom_fields'=>['role_secret'=>'Exact '.$kind.' secret field']];if($kind==='news')$data['news_date']='2098-05-04';else$data['event_start']='2098-05-04T19:00';$item=$pages->save($data);$item=$pages->publish($item['id'],$item['version']);if($kind==='news')$projection=(new Articles($db,$reader))->publicList();else$projection=(new Kulturhus\Native\Cms\Events($db,$admin->club()))->publicId($item['id']);check(!str_contains(json_encode($projection,JSON_THROW_ON_ERROR),'Exact '.$kind.' secret field'),'actual '.$kind.' public adapter never leaks field data through an administrator or trusted worker');}
